    20→
    21→public class BlockValidator(
    22→    ITxValidator? txValidator,
    23→    IHeaderValidator? headerValidator,
    24→    IUnclesValidator? unclesValidator,
    25→    ISpecProvider? specProvider,
    26→    ILogManager? logManager)
    27→    : IBlockValidator
    28→{
    29→    private readonly IHeaderValidator _headerValidator = headerValidator ?? throw new ArgumentNullException(nameof(headerValidator));
    30→    private readonly ITxValidator _txValidator = txValidator ?? throw new ArgumentNullException(nameof(txValidator));
    31→    private readonly IUnclesValidator _unclesValidator = unclesValidator ?? throw new ArgumentNullException(nameof(unclesValidator));
    32→    private readonly ISpecProvider _specProvider = specProvider ?? throw new ArgumentNullException(nameof(specProvider));
    33→    private readonly BlockDecoder _blockDecoder = new();
    34→    private readonly ILogger _logger = logManager?.GetClassLogger() ?? throw new ArgumentNullException(nameof(logManager));
    35→
    36→    public bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle) =>
    37→        _headerValidator.Validate(header, parent, isUncle, out _);
    38→
    39→    public bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle, out string? error) =>
    40→        _headerValidator.Validate(header, parent, isUncle, out error);
    41→
    42→    /// <summary>
    43→    /// Applies to blocks without parent
    44→    /// </summary>
    45→    /// <param name="block">A block to validate</param>
    46→    /// <param name="error">Error description in case of failed validation</param>
    47→    /// <returns>Validation result</returns>
    48→    /// <remarks>
    49→    /// Parent may be absent during BeaconSync
    50→    /// </remarks>
    51→    public bool ValidateOrphanedBlock(Block block, out string? error)
    52→    {
    53→        if (!ValidateEip4844Fields(block, _specProvider.GetSpec(block.Header), out error))
    54→            return false;
    55→
    56→        error = null;
    57→        return true;
    58→    }
    59→
    60→    /// <summary>
    61→    /// Suggested block validation runs basic checks that can be executed before going through the expensive EVM processing.
    62→    /// </summary>
    63→    /// <param name="block">A block to validate</param>
    64→    /// <param name="parent">Parent of the block</param>
    65→    /// <param name="errorMessage">Message detailing a validation failure.</param>
    66→    /// <param name="validateHashes"></param>
    67→    /// <returns>
    68→    /// <c>true</c> if the <paramref name="block"/> is valid; otherwise, <c>false</c>.
    69→    /// </returns>
    70→    public bool ValidateSuggestedBlock(Block block, BlockHeader? parent, out string? errorMessage, bool validateHashes = true)
    71→    {
    72→        IReleaseSpec spec = _specProvider.GetSpec(block.Header);
    73→
    74→        int encodedSize = block.EncodedSize ?? _blockDecoder.GetLength(block, RlpBehaviors.None);
    75→        if (spec.IsEip7934Enabled && encodedSize > spec.Eip7934MaxRlpBlockSize)
    76→        {
    77→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} RLP encoded size of {encodedSize} bytes exceeds the max limit of {spec.Eip7934MaxRlpBlockSize} bytes");
    78→            errorMessage = BlockErrorMessages.ExceededBlockSizeLimit(spec.Eip7934MaxRlpBlockSize);
    79→            return false;
    80→        }
    81→
    82→        if (!ValidateTransactions(block, spec, out errorMessage))
    83→        {
    84→            return false;
    85→        }
    86→
    87→        if (!ValidateEip4844Fields(block, spec, out errorMessage))
    88→        {
    89→            return false;
    90→        }
    91→
    92→        if (spec.MaximumUncleCount < block.Uncles.Length)
    93→        {
    94→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Uncle count of {block.Uncles.Length} exceeds the max limit of {spec.MaximumUncleCount}");
    95→            errorMessage = BlockErrorMessages.ExceededUncleLimit(spec.MaximumUncleCount);
    96→            return false;
    97→        }
    98→
    99→        if (validateHashes && !ValidateUnclesHashMatches(block, out Hash256 unclesHash))
   100→        {
   101→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Uncles hash mismatch: expected {block.Header.UnclesHash}, got {unclesHash}");
   102→            errorMessage = BlockErrorMessages.InvalidUnclesHash;
   103→            return false;
   104→        }
   105→
   106→        if (block.Uncles.Length > 0 && !_unclesValidator.Validate(block.Header, block.Uncles))
   107→        {
   108→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Invalid uncles");
   109→            errorMessage = BlockErrorMessages.InvalidUncle;
   110→            return false;
   111→        }
   112→
   113→        bool blockHeaderValid = _headerValidator.Validate(block.Header, parent, false, out errorMessage);
   114→        if (!blockHeaderValid)
   115→        {
   116→            if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Invalid header");
   117→            return false;
   118→        }
   119→
   120→        if (validateHashes)
   121→        {
   122→            if (!ValidateTxRootMatchesTxs(block, out Hash256 txRoot))
   123→            {
   124→                if (_logger.IsDebug) _logger.Debug($"{Invalid(block)} Transaction root hash mismatch: expected {block.Header.TxRoot}, got {txRoot}");
   125→                errorMessage = BlockErrorMessages.InvalidTxRoot(block.Header.TxRoot!, txRoot);
   126→                return false;
   127→            }
   128→
   129→            if (!ValidateWithdrawals(block, spec, out errorMessage))
   130→            {
   131→                return false;
   132→            }
   133→        }
   134→
   135→        return true;
   136→    }
   137→
   138→    /// <summary>
   139→    /// Processed block validation is comparing the block hashes (which include all other results).
   140→    /// We only make exact checks on what is invalid if the hash is different.
   141→    /// </summary>
   142→    /// <param name="processedBlock">This should be the block processing result (after going through the EVM processing)</param>
   143→    /// <param name="receipts">List of tx receipts from the processed block (required only for better diagnostics when the receipt root is invalid).</param>
   144→    /// <param name="suggestedBlock">Block received from the network - unchanged.</param>
   145→    /// <returns><c>true</c> if the <paramref name="processedBlock"/> is valid; otherwise, <c>false</c>.</returns>
   146→    public bool ValidateProcessedBlock(Block processedBlock, TxReceipt[] receipts, Block suggestedBlock) =>
   147→        ValidateProcessedBlock(processedBlock, receipts, suggestedBlock, out _);
   148→
   149→    /// <summary>
   150→    /// Processed block validation is comparing the block hashes (which include all other results).
   151→    /// We only make exact checks on what is invalid if the hash is different.
   152→    /// </summary>
   153→    /// <param name="processedBlock">This should be the block processing result (after going through the EVM processing)</param>
   154→    /// <param name="receipts">List of tx receipts from the processed block (required only for better diagnostics when the receipt root is invalid).</param>
   155→    /// <param name="suggestedBlock">Block received from the network - unchanged.</param>
   156→    /// <param name="error">Detailed error message if validation fails otherwise <value>null</value>.</param>
   157→    /// <returns><c>true</c> if the <paramref name="processedBlock"/> is valid; otherwise, <c>false</c>.</returns>
   158→    public bool ValidateProcessedBlock(Block processedBlock, TxReceipt[] receipts, Block suggestedBlock, out string? error)
   159→    {
   160→        if (processedBlock.Header.Hash == suggestedBlock.Header.Hash)
   161→        {
   162→            error = null;
   163→            return true;
   164→        }
   165→
   166→        if (_logger.IsWarn) _logger.Warn($"Processed block {processedBlock.ToString(Block.Format.Short)} is invalid:");
   167→        if (_logger.IsWarn) _logger.Warn($"- hash: expected {suggestedBlock.Hash}, got {processedBlock.Hash}");
   168→        error = null;
   169→        if (processedBlock.Header.GasUsed != suggestedBlock.Header.GasUsed)
   170→        {
   171→            if (_logger.IsWarn) _logger.Warn($"- gas used: expected {suggestedBlock.Header.GasUsed}, got {processedBlock.Header.GasUsed} (diff: {processedBlock.Header.GasUsed - suggestedBlock.Header.GasUsed})");
   172→            error ??= BlockErrorMessages.HeaderGasUsedMismatch(suggestedBlock.Header.GasUsed, processedBlock.Header.GasUsed);
   173→        }
   174→
   175→        if (processedBlock.Header.Bloom != suggestedBlock.Header.Bloom)
   176→        {
   177→            if (_logger.IsWarn) _logger.Warn($"- bloom: expected {suggestedBlock.Header.Bloom}, got {processedBlock.Header.Bloom}");
   178→            error ??= BlockErrorMessages.InvalidLogsBloom(suggestedBlock.Header.Bloom, processedBlock.Header.Bloom);
   179→        }
   180→
   181→        if (processedBlock.Header.ReceiptsRoot != suggestedBlock.Header.ReceiptsRoot)
   182→        {
   183→            if (_logger.IsWarn) _logger.Warn($"- receipts root: expected {suggestedBlock.Header.ReceiptsRoot}, got {processedBlock.Header.ReceiptsRoot}");
   184→            error ??= BlockErrorMessages.InvalidReceiptsRoot(suggestedBlock.Header.ReceiptsRoot, processedBlock.Header.ReceiptsRoot);
   185→        }
   186→
   187→        if (processedBlock.Header.StateRoot != suggestedBlock.Header.StateRoot)
   188→        {
   189→            if (_logger.IsWarn) _logger.Warn($"- state root: expected {suggestedBlock.Header.StateRoot}, got {processedBlock.Header.StateRoot}");
   190→            error ??= BlockErrorMessages.InvalidStateRoot(suggestedBlock.Header.StateRoot, processedBlock.Header.StateRoot);
   191→        }
   192→
   193→        if (processedBlock.Header.BlobGasUsed != suggestedBlock.Header.BlobGasUsed)
   194→        {
   195→            if (_logger.IsWarn) _logger.Warn($"- blob gas used: expected {suggestedBlock.Header.BlobGasUsed}, got {processedBlock.Header.BlobGasUsed}");
